    "title": "临济宗开山祖师",
    "era": "唐代 (?-867)",
    "lifeStory": "义玄禅师，曹州南华（今山东东明）人，俗姓邢。幼而颖异，落发受具后，精究律藏，既而叹曰：“此济世之医方也，非教外别传之旨。”遂更衣游方，首参黄檗希运。在黄檗会下三年，行业纯一。时首座睦州陈尊宿勘问：“上座在此多少时？”师曰：“三年。”睦州曰：“曾参问否？”师曰：“不曾参问，不知问个什么？”睦州曰：“汝何不去问和尚：如何是佛法的大意？”师便去问，声未绝，黄檗便打。师退，睦州曰：“问语作么生？”师曰：“某甲问声未绝，和尚便打，某甲不会。”睦州曰：“但更去问。”师又去问，黄檗又打。如是三问三打。师回谓睦州曰：“幸蒙慈悲，令某甲问讯和尚，三度发问，三度被打。自恨障缘，不领深旨，今且辞去。”睦州曰：“汝若去，须辞和尚了去。”师礼拜退。\n\n睦州先到黄檗处曰：“问话上座虽是后生，却甚奇特。若来辞，方便接伊，已后为一株大树覆荫天下人去在。”师来日辞，黄檗曰：“不得往别处去，汝向高安滩头大愚处去。”师至大愚处，具说三度被打因缘，问：“不知某甲有过无过？”大愚曰：“黄檗与么老婆心切，为汝得彻困，更来这里问有过无过？”师于言下大悟，曰：“元来黄檗佛法无多子！”归黄檗，黄檗问：“这汉来来去去，有甚了期？”师曰：“只为老婆心切。”遂将大愚之言举似，黄檗曰：“大愚老汉饶舌，待来痛与一顿。”师曰：“说甚待来，即今便打。”随后便掴，黄檗曰：“这风颠汉却来这里捋虎须。”师便喝。自此机锋峻烈，天下莫及。\n\n后住镇州（今河北正定）临济禅院，建立黄檗宗旨，以四料简、四照用、四宾主、三玄三要、四喝八棒等施设接人，禅风如迅雷烈风，天下归之，是为临济宗。咸通八年（867年）示寂，谥“慧照禅师”，塔名“澄灵”。临济一宗后分杨岐、黄龙二派，宋元以降法脉最盛，流传至今，并远播日韩。",
    "teachings": "义玄之教，贵在“真正见解”：赤肉团上有一无位真人，常从汝等诸人面门出入——听法的、说法的、目前历历孤明的这个，即是。他痛斥向外驰求：求佛求法是造地狱业，看经看教亦是造业；逢佛杀佛，逢祖杀祖，逢罗汉杀罗汉，逢父母杀父母，始得解脱。又立四料简（夺人不夺境、夺境不夺人、人境俱夺、人境俱不夺）勘验学人，四喝八棒施设峻烈。其宗风“随处作主，立处皆真”，为禅门最雄健之一脉。",
    "quotes": [
      "赤肉团上有一无位真人，常从汝等诸人面门出入。 —《临济录》",
      "随处作主，立处皆真。 —《临济录》",
      "逢佛杀佛，逢祖杀祖，逢罗汉杀罗汉，逢父母杀父母，始得解脱。 —《临济录》",
      "你只看目前听法底人，无形无相，无根无本，无住处，活泼泼地。 —《临济录》"
],
