    "lifeStory": "维摩诘（Vimalakīrti），意译为“无垢称”，古印度毗耶离城大富长者，金粟如来之后身示现。虽在居家执持世俗产业，而心常在无上顿悟大定。在《维摩诘所说经》中，维摩诘称病示疾，弹叱舍利子、目犍连、大迦叶、弥勒菩萨等小乘与大乘执相习气，最终以“维摩一默如雷震”直示入不二法门，成为千年来禅宗居士见性成佛的第一模范标杆。",
