    "teachings": "曹山承洞山五位君臣之旨，以“正中偏、偏中正、正中来、偏中至、兼中到”配君臣五位，明体用回互、理事圆融之妙。其教贵在“回互”——不偏于理，不偏于事，于回互中显中道之旨。 其教法直指心源，宗风峻拔圆融。强调佛法不在言句名相，而在当下自心觉照；行住坐卧四威仪中不离本真，随缘任运，不住有无二边。主张真修实证，解行相应，破除学人死执经教与枯坐盲修之偏，导归大乘见性成佛、游戏三昧之无上菩提。",
