    "era": "唐代 (780-841)",
    "lifeStory": "宗密禅师，果州西充（今四川西充）人，俗姓何。家世儒业，少通儒学。后读《圆觉经》深有感悟，遂出家。先承华严宗澄观之学，为华严宗第五祖；后又承荷泽神会一系禅法，以“教禅一致”为宗。师住圭峰草堂寺，着《圆觉经大疏》《禅源诸诠集都序》《原人论》等，融会华严与禅宗，倡“顿悟渐修”之旨。师谓顿悟如开目，渐修如行路——悟理一念顿了，断习须渐渐磨治。",
