    "lifeStory": "宗杲禅师，宣州宁国（今安徽宁国）人，俗姓奚。十七岁出家，后参圆悟克勤，于克勤座下开悟。克勤以《碧岩录》付之，令掌记室。师先后住径山、育王、云居等大刹，道法之盛，冠绝一时。然因主战派张九成往来密切，遭秦桧忌恨，被褫夺衣牒，流放衡州、梅州十六年。赦还后重住径山，道俗归向如初。师倡“看话禅”——以公案中一话头（如“狗子无佛性”之“无”字）为所缘，集中心力，逼拶至思量不及处，忽然契悟。与曹洞宗宏智正觉之“默照禅”相对，后世禅宗多承看话一脉。师曾焚毁《碧岩录》刻板，恐学人死于文字，然此书终传于世。",
    "teachings": "大慧之教，以“看话头”为宗：提一话头，如“狗子还有佛性也无？州云：无。”只管理会“无”字，不得作道理会、不得作有无会、不得作卜度会。如老鼠咬棺材，无出路处，忽然咬透，便是大彻大悟。其教贵在“疑情”——以一疑逼拶到底，疑到极处，便是悟时。",
