    "lifeStory": "崇信禅师，渚宫（今湖北江陵）人。初于天皇道悟座下服役，悟道后住澧州龙潭山。师以“点灯”公案接引德山宣鉴：德山侍立许久，师曰：“更深，何不下去？”德山揭帘出，又回曰：“外面黑。”师点一纸烛与之，德山伸手接时，师忽然吹灭，德山于此大悟——一切经教言说如纸烛之光，吹灭之后，方见自家本有之光明。此一吹，吹出德山一生“棒打”之宗风。",
