    "lifeStory": "师备禅师，福州闽县（今福建福州）人，俗姓谢，幼年垂钓南台江，世称“谢三郎”。唐咸通初年届三十，忽慕出尘，弃钓舟投芙蓉山灵训禅师落发，往钟陵开元寺道玄律师处受具足戒。与雪峰义存为法门昆季，一日携囊出岭欲遍参诸方，磕伤脚指，流血痛楚之际豁然有省，叹曰：“是身非有，痛从何来？”遂回雪峰。雪峰问何不遍参，师答：“达摩不来东土，二祖不往西天。”峰然之，屡赞“备头陀再来人也”。后阅《楞严经》发明心地，应机敏捷，与修多罗冥契。光化初，闽王王审知请为安国禅院开山，奏赐紫袈裟、“宗一大师”之号，座下常七百余人。闽王尝请师与雪峰入内论佛心印，师直告“有作之心皆是轮回”，为王授真如十一名目。开平二年（908）示灭，世寿七十四。门下罗汉桂琛传清凉文益，开出法眼一宗。",
    "teachings": "玄沙宗风绵密，以“辨缁素、破儱侗”为要务：痛斥笼统真如之见，主张明是明、暗是暗，混滥分毫不得。其勘“昭昭灵灵”为认贼为子之识神，示“秘密金刚体”圆成正遍、遍周沙界。接机立“三句纲宗”：第一句自承当、现成具足，第二句回因就果、转位投机，第三句明阴洞阳、慈定之门，与云门三句遥相呼应。又垂“三种病人”之语，勘尽诸方接人手段。",
