    "lifeStory": "桂琛禅师，常山（今浙江常山）人，俗姓李。初学唯识，后参玄沙师备，于师备座下开悟。师住漳州罗汉院，以“一切现成”接引法眼文益：文益参师，遇雪阻留，师问：“作什么行脚？”文益曰：“寻访知识。”师曰：“行脚人三句中须辨，两句中须明，一句中须具。只如一句中，作么生辨？”文益无语。师曰：“不知若何，且坐吃茶。”后文益辞行，师送至门外，曰：“上座寻常说‘三界唯心，万法唯识’，且道脚下这块石头，是在心内还是在心外？”文益曰：“在心内。”师曰：“行脚人着甚来由，安一块石头在心头？”文益大窘，乃留止月余，终于言下大悟“一切现成”之旨。",
