    "era": "唐代 (约9世纪)",
    "lifeStory": "道明禅师，江南（今浙江）人，俗姓陈，世称“陈尊宿”。住睦州（今浙江建德），常织蒲鞋卖以养母，故又称“蒲鞋禅师”。师接人机锋峻烈，每有学人来参，辄闭门不纳。云门文偃初参师，师亦闭门，文偃于门缝间挤断一足，当下大悟——师之“闭门”，实为最上利根之直指：于学人将入未入之际，截断其意识流，令自见本来。师指示文偃往参雪峰义存，遂开云门一宗。",
