    "era": "北宋 (1025–1100)",
    "lifeStory": "晦堂祖心（1025—1100），广东始兴人，俗姓邬。幼岁颖悟，十九岁试经得度，博涉大小乘经论。后投黄龙山参谒黄龙慧南大师于积翠峰，深蒙印可，成为慧南大师座下之上首法嗣。宋熙宁二年（1069）慧南圆寂，祖心继主黄龙山道场三十余载，提撕英秀，四方学者奔凑。宋哲宗赐号‘宝觉禅师’。禅师宗风峭拔而慈和，接引学者以‘黄龙拳头’打破触背牢关；又以‘木犀天香’直截点化北宋大文豪黄山谷（黄庭坚）彻见自性本心，成为禅林千古美谈。枢密副使王韶、御史徐禧皆深相礼敬。宋元符三年（1100）端坐示寂，世寿七十六，僧腊五十六。",
    "teachings": "晦堂继承黄龙慧南大师正统宗风，主张参禅必须直明自家心性田地。痛斥以知见分别作佛法，提倡‘欲得大用现前，但可顿忘诸见’。在方丈室中常握拳示人：‘若作拳见即触，不作拳见即背。上座如何见？’以此触背两关绝断学者意识退路。极力提倡平常心是道，示人向上大事不过是‘著衣吃饭’，于家常日用与声色见闻中直认本来面目，无遮无障，全提正印。",
