    "lifeStory": "丹霞子淳禅师，剑州梓潼（今四川梓潼）人，俗姓贾。幼依县之大安寺为童子，年二十七祝发受具，礼道凝上人为师，通贯教乘。后遍参真如慕喆、真净克文、大洪法恩诸师，终入芙蓉道楷之门，叩以大事，于言下大悟。侍道楷有年，道楷深器重之，以为洞上孤宗斯人可托。崇宁间住南阳丹霞山，后迁唐州大乘山、随州大洪山，举扬曹洞禅风，学众千人，盛冠诸方。门下出宏智正觉、真歇清了等七大弟子，曹洞宗由此中兴。宣和元年示寂，世寿五十四，塔全身于洪山之南。师着《虚堂集》三卷、《丹霞子淳禅师语录》二卷传世。",
    "teachings": "丹霞宗风承曹洞“回互”之旨，宏唱五位君臣之法，横说竖说如转圆石于千仞之上。师以“绵密”为特色，不尚峻烈机锋，于绵密细致中层层拨开，令学人自悟。尝上堂云：“乾坤之内，宇宙之间，有一件宝贝，秘藏在形山。”以拄杖敲击曰：“白鹭立雪，颜色不同；明月芦花，亦不相似。”——此语为曹洞宗经典开示。",
