    "lifeStory": "芙蓉道楷禅师，沂州沂水（今山东沂水）人，俗姓崔。幼好隐遁，少学辟谷之术于伊阳山中，后悟其非，弃而习佛。于京师术台寺试《法华》得度受具戒。后参投子义青于白云山海会寺，问：“佛祖言句如家常茶饭，离除此之外别有为人言句也无？”青曰：“汝道寰中天子勅，还假禹汤尧舜也无？”楷拟酬之，青以拂子摵之曰：“汝发意来早有二十棒也。”于是悟旨于言下。元丰五年（1082）出世，初住沂州仙洞山，后历住洛阳招提、龙门山、郢州大阳山、随州大洪山，大扬洞上之风。崇宁三年（1104），徽宗召住京师十方净因禅院，赐紫衣及“定照禅师”号。师以“常发誓愿不受利名”固辞不受，帝怒，黥流淄州，师恬然就刑。明年冬敕放自便，遂结庵芙蓉湖中，学者风从。政和七年（1117）赐额“华严禅寺”，翌年五月十四日书偈示寂，世寿七十六。法嗣二十九人，以丹霞子淳最为杰出。着有《芙蓉道楷禅师语要》一卷。",
    "teachings": "芙蓉宗风以“刚劲孤硬”著称，不慕名利，守道自足。师示众云：“夫出家者为厌尘劳，求脱生死。休心息念，断绝攀缘……直须两头撒开，中间放下。遇声遇色，如石上栽花。见利见名，似眼中着屑。”其辞赐号之举，示禅僧应以道为重，不以世俗荣辱动心，为后世丛林气节之典范。门下丹霞子淳承其法脉，再传宏智正觉，开曹洞宗中兴之局。",
