    "lifeStory": "明本禅师，钱塘（今浙江杭州）人，俗姓孙。少出家，参高峰原妙，于原妙座下开悟。师不住寺院，随处结庵而居，世称“中峰和尚”。师之教以“参禅无秘诀，只要生死心切”为宗，承临济看话禅之传统。师与赵孟頫交游甚密，赵孟頫从之参禅。师著《天目中峰和尚广录》，以禅净合流为特色，对元代禅宗影响深远。日本禅僧纷纷来华参学于师，师对日本禅宗影响极大。",
