    "name": "天衣义怀",
    "title": "云门宗 / 雪窦重显法嗣 / 禅净双修先驱",
    "era": "北宋 (989-1060)",
    "lifeStory": "天衣义怀禅师，永嘉乐清（今浙江乐清）人，俗姓陈。家世以渔为业，幼时常坐船尾，父得鱼付师贯之，师不忍，私投江中，父怒笞之，恬然如故。长游京师，依景德寺为童行。天圣中试经得度。初参金銮善、叶县归省，皆不契。后东游至姑苏翠峰，谒雪窦重显。显问：“汝名甚么？”曰：“义怀。”显曰：“何不名怀义？”如是数度被打。寻为水头，一日汲水折担，忽悟，作偈曰：“一二三四五六七，万仞峰头独足立。骊龙颔下夺明珠，一言勘破维摩诘。”显闻拊几称善印可。后七迁法席，自铁佛至天衣，所到皆兴其荒废，大振云门法道。法嗣八十余人，有慧林圆照、法云法秀、长芦应夫、佛日智才等。晚以疾居池州杉山庵，门人智才迎归杭州佛日山。才如姑苏未还，怀促其归，至门而示寂，世寿七十二。崇宁中敕谥“振宗大师”。师倡禅净双修，令学人“一心念佛”兼参公案，为宋代禅净合流之重要桥梁。",
    "teachings": "天衣宗风承云门“涵盖乾坤”之旨，以直指为宗。师上堂云：“雁过长空，影沉寒水。雁无遗踪之意，水无留影之心。若能如是，方解向异类中行。”此语传诵禅林。师兼倡禅净双修，以念佛摄心、参禅悟道并举，开宋代禅净合流之先声。",
