    "lifeStory": "寒山子，唐代著名隐逸诗僧，隐居天台翠屏山寒岩，因以为号。与国清寺拾得相亲善，以食堂残滓为食，而神游物外，出口成诗。其诗或劝世、或说禅、或咏山水，语浅而旨深，谚云“家有寒山诗，胜汝看经卷”。后人辑为《寒山子诗集》，流传东瀛，为日本禅林所重。相传为文殊化身，与拾得（普贤化身）并称“和合二仙”。其诗“吾心似秋月，碧潭清皎洁”为禅诗千古绝唱。",
