    "lifeStory": "姚广孝（1335-1418），幼名天僖，法名道衍，号独庵老人，长洲（今江苏苏州）人。明代著名禅僧、政治家。早年出家参禅，通达三教典籍与兵家奇谋。佐燕王朱棣靖难成大业，官至太子少师。虽居高位显贵，仍终生着僧服、居僧舍，退朝后唯以禅诵著述为事，著有《诸上善人咏》等，展现了深厚的自性定力与大机大用。",
