    "era": "唐 (约9世纪)",
    "lifeStory": "龙潭崇信禅师，唐代禅僧，渚宫人，天皇道悟法嗣。初在道悟门下执役炊爨，随侍多年。一日问师：“某自到来，不蒙指示心要。”道悟云：“自汝到来，吾未尝不指汝心要。汝擎茶来，吾为汝接；汝行食来，吾为汝受；汝和南时，吾便低首。何处不指示心要？”崇信低头良久，道悟曰：“见则直下便见，拟思即差。”师当下开悟。后于澧阳龙潭出世，以“夜深吹灭纸烛”令德山宣鉴大悟烧却疏钞，为宗门千古佳话。",
