    "teachings": "泛用佛经禅语著书立说，注四书皆用佛法。所用量子如虚灵不昧、真实无妄、一旦豁然贯通等皆出佛经禅语。然密设墙壍排佛，令后学不看佛书。 其教法直指心源，宗风峻拔圆融。强调佛法不在言句名相，而在当下自心觉照；行住坐卧四威仪中不离本真，随缘任运，不住有无二边。主张真修实证，解行相应，破除学人死执经教与枯坐盲修之偏，导归大乘见性成佛、游戏三昧之无上菩提。",
