    "lifeStory": "密庵咸杰，俗姓吴，福州福清人。出家后行脚参方，参应庵昙华禅师于衢州明果山，一见便明大法，为应庵嗣法弟子。应庵为虎丘绍隆嗣法，虎丘为圆悟克勤嗣法——密庵为圆悟法孙，杨岐虎丘系之重要传人。一生七镇名山：衢州乌巨山干明禅院（乾道三年八月一日受请）、大中祥符寺、蒋山太平兴国寺、常州华藏寺、径山兴圣万寿寺、灵隐景德寺、天童景德寺。道满天下，门下出松源崇岳、破庵祖先、曹源道生等，为南宋临济宗中坚。入对中宸，阐扬般若，深契上意。以破沙盆语闻名丛林。淳熙十三年示寂，塔铭由正议大夫刑部尚书葛邲撰。",
    "teachings": "密庵宗风以破沙盆为标识——接机峻烈不留情面，打破一切窠臼直指人心。其法语直截痛快——佛说一切法为度一切心我无一切心何用一切法。其入方丈据座——此室甚深广大非语默可及，不入洪波里争见弄潮人。其评古德凌厉痛快——二尊宿美则美矣若要扶临济正宗每人各欠一顿棒在。其颂古九则以诗偈重显古则，文采与禅机并美。其法语直示祖师门下直截省要不历阶梯立地成佛，力斥太杀现成不肯承当一味钻头入知见网中之口头禅。",
