    "name": "龙钦巴尊者",
    "title": "大圆满集大成者 / 遍知法王",
    "era": "西藏前藏（1308-1364）",
    "lifeStory": "龙钦巴（意译\"大广智\"，尊称\"遍知法王\"），法名智美沃色，宁玛派史上最伟大的理论集成者。生于前藏优如扎恰却仲，五岁识字诵经，七岁起学医、历算、声明，十二岁出家，遍依当时宁玛、噶当、萨迦诸师，显密兼通。曾于桑耶秦浦亲见莲师父母，获《空行宁提》传承；后依止智悲光前身至尊咕玛拉扎卓绝修行。一生闭关数十年，著述逾二百五十部，《七宝藏》《三大休息》《三自解脱》合称宁玛派教法之巅峰，其中《大圆满心性休息》以十三品带自释，从暇满难得一路讲到直指心性，被誉为雪域修心宝典之冠。五十六岁于桑耶青浦示寂，空中天乐弥满，舍利无数。其学说经吉美林巴取伏藏《龙钦宁提》而再度中兴，成为近代宁玛派修行体系的主干。今日谈大圆满，几乎无人能绕过龙钦巴立下的义理框架。",
    "teachings": "龙钦巴的教法次第井然而落点极明：由暇满、无常、轮回、业果四共前策动出离，依师皈依发心筑基，经寂止胜观调柔其心，最后第九品越过一切台阶直指——自心本性即是普贤王，非修非造，本自光明任运。识得本来面目者，生死当下即涅槃。他教人不要把大圆满当作玄谈的装饰品：不具前行之基而侈谈直指，如于冰上筑高楼。",
    "quotes": [
      "观察自心无自性，生住异灭不可得。",
      "外境如梦心如幻，明空双运绝戏论。",
      "识得本来面目者，生死当下即涅槃！"
    ],
