    "title": "大手印传承开祖 / 八十四大成就者之首",
    "era": "印度（988-1069）",
    "lifeStory": "帝洛巴，藏传噶举派尊为初祖，印度八十四大成就者之首。生于东印度萨霍尔地方婆罗门家，为榕树园中修行之瑜伽士。相传亲从金刚总持受法，复依止因扎菩提、拉瓦巴、那洛巴系统等上师，尽得密集、胜乐等四部密续与大哥印口诀。长年以榨芝麻维持生计，兼行苦行，故号\"帝洛\"（捣芝麻者）。其最著名的教化对象是那洛巴：那洛巴身为那烂陀寺首座，为求大手印心要，随帝洛巴十二年，历十二大苦行、十二小苦行，备受折磨而信心不退，终于河畔得受《恒河大手印》等心髓口诀——帝洛巴于恒河岸边以歌唱形式直指心性，此颂至今为噶举派根本圣典。弟子那洛巴传玛尔巴，玛尔巴传密勒日巴，是为噶举\"四大八小\"诸派之源。大手印与大圆满并称印藏心性法门之双峰：一以俱生智印契，一以本觉任运，归元无二。",
    "teachings": "帝洛巴的大手印教法至简至峻：大手印不可言说，无断无得，如仰观太虚空，无一处可指认，而明性自明。功夫不在修造，而在不修之修——莫思莫虑莫观照，莫随莫制任运住。若以有所得心强自修定，禅定反成系缚；识得本明，则烦恼即菩提，生死即涅槃。",
    "quotes": [
      "莫思莫虑莫观照，莫随莫制任运住。",
      "烦恼当下即菩提，生死即是大涅槃。"
    ],
