    "lifeStory": "中天竺人，从第十一祖富那夜奢得法，为禅宗西天第十二祖。辩才宏博，善于音律，作梵呗悲调化导群机，马闻其音悲鸣不食，故号“马鸣”。造《大乘起信论》、《大庄严经论》、《佛所行赞》等，摧伏外道，大阐大乘心性法门。",
