    "title": "庞公之女 / 宗门千古神化大士",
    "era": "唐代 (8-9世纪)",
    "lifeStory": "灵照女，唐代襄阳庞蕴居士之女。幼承家风，聪颖通玄。随父庞居士散尽家财后，居于草庵，以编织竹漉篱奉养父母。机锋迅疾，深明第一义谛，屡与丹霞天然、药山门下大德交锋，丝毫不让。居士曾问：“古人道：明明百草头，明明祖师意，如何会？”灵照云：“老老大大作这个语话！明明百草头，明明祖师意。”居士将入灭，命灵照视日早晚，灵照诳报日蚀，趁庞公出户观日之际，遽登父座合掌坐亡。庞公叹曰：“我女锋捷矣！”其解脱自在，冠绝古今，为禅门女尊之至极典范。",
    "teachings": "灵照禅风峻拔迅捷，主张“也不难，也不易，百草头上祖师意”，直契触目菩提；以坐脱立亡之大机用破除世间一切情执爱网，示现自性本来解脱、无男女相、无生死相之究竟风范。",
    "quotes": [
      "也不难，也不易，百草头上祖师意。",
      "明明百草头，明明祖师意。",
      "见爷倒地，某甲相扶。"
    ],
