    "name": "希叟绍昙",
    "title": "南宋杨岐宗匠 · 四主名刹金钉子",
    "era": "宋代",
    "lifeStory": "希叟绍昙禅师（？—1297），南宋临济宗杨岐派高僧。参学圆照一禅师而大彻大悟，深契杨岐正脉。禅师道风峭拔坚刚，机锋峻烈，不容学者拟议，丛林盛誉为‘撑拓宗门之铮然金钉子’。先后应请住持庆元府佛陇寺、平江府法华禅寺、庆元府雪窦资圣禅寺以及瑞岩山开善崇庆禅寺四座江南名刹，名重两朝。其时正值日本东渡求法鼎盛期，镰仓建长寺兰溪道隆门下弟子多渡海执经问难，师广为接引印可，临终坐化荼毗舍利无数，为东亚禅宗文化交流之法源重镇。",
    "teachings": "希叟绍昙接人提持极重‘金钉铁铆、截断葛藤’之向上全提。示众常教人‘目前无法，意在目前’，不可向言句纸墨里寻死路，须亲证顶门金刚正眼。其宗风既有临济棒喝纵夺之险绝，又有于柴米运水日用处全提本真之平实。警示学者做工夫须如生铁铸就、金刚打成，直教佛来魔来一齐斩断，方见自性真山真水。",
    "quotes": [
      "目前无法，意在目前。不是目前法，非耳目之所到。",
      "千圣顶门一眼，灼然烁破虚空。更若向言句里捞摸，大似望空捕影。",
      "雪窦千寻瀑布，自古喷薄雷轰。只要汝等个个如生铁铸就、金刚打成！",
      "莫向沧溟弄钓钩，归去建长重举起！"
    ],
