    "era": "元代 (1265–1334)",
    "lifeStory": "无见先睹（1265—1334），号无见，浙江南浔人，俗姓俞。元代临济宗破庵派高僧。幼岁颖悟出家，参谒径山断桥妙伦、育王无准师范诸尊宿，后嗣法于方山文宝禅师，得破庵派大机大用真髓。元成宗大德年间隐遁天台华顶峰善兴禅寺，大坐绝顶四十载，足不及尘寰。宗风峻烈严冷，四方参徒梯山航海云集。与中峰明本禅师遥相照应，东南学者奉二人为‘元代东南二大甘露门’。元统二年（1334）端坐示寂，世寿七十，僧腊五十四。门人道昌编集语录，翰林学士黄溍撰序，同参天台昙噩撰塔铭，日本道澄等东瀛禅僧录序传颂，法化普洽海内外。",
    "teachings": "先睹禅师继承破庵‘大机大用、全提杀活’之家风，示人参禅必须极力壁立千仞。极力主张‘四绝路头’（绝思量分别、绝见闻觉知、绝行住坐卧、绝问答语言），唯单提一句‘赵州无字’或‘念佛是谁’，向绝消息处死力拶去。严厉呵斥‘脱空妄语’与死守‘鹘臭布衫’（执着玄妙境界与悟迹不舍），主张彻见本来后当打碎光影窟穴，赤洒洒任运施为。其诗偈与示众法语笔力雄健，宗眼圆明，横扫凡圣关隘。",
    "quotes": [
      "若向笔尖头上弄虚头，说黄道黑，瞒得他人，瞒不得阎家老子。",
      "百千三昧，无量法门，天下老和尚舌头，总被此四绝路头截断了也。",
      "脱去鹘臭布衫，打碎光影鬼窟，直得净裸裸赤洒洒，犹是化城，更须透过始得。",
      "华顶峰头独坐时，寒风卷雪入枯篱。沙鸥冷眼知深意，不向浮云问所思。"
    ],
