    "era": "唐代 (684-762)",
    "lifeStory": "无相禅师（684-762），俗姓金，新罗国王族（海东金氏王子）。出家后泛海入唐，西行入蜀参资州德纯寺处寂禅师，受传法衣。开元二十年入成都开创净泉寺（净众寺），开演禅法二十余载，巴蜀士庶尊称为‘金和尚’。每至冬夏大会，先引声念佛，气尽声绝，即宣说‘无忆、无念、莫妄’三句法语。唐玄宗避乱入蜀时曾躬迎设礼。晚年密付达摩信袈裟与心法于保唐无住。",
    "teachings": "首倡‘无忆是戒，无念是定，莫妄是慧’三句总持法印。不思量过去即是无忆，不攀缘未来即是无念，现前不起虚妄计度即是莫妄。三句赅摄三学，直契自性本净。",
