    "title": "临济杨岐派一代宗匠·天湖禅师",
    "era": "元代 (1272-1352)",
    "lifeStory": "石屋清珙禅师（1272-1352），苏州常熟人，俗姓温。幼依崇福寺出家，受具后登天目山参礼临济宗巨擘高峰原妙，参‘万法归一’三年未悟。后承高峰旨意往建阳参及菴信禅师，屡呈见解皆被斥为死句。发愤辞去，行至风亭见长空寥廓豁然大悟，呈‘清明时节雨初晴，黄莺枝上分明语’，获及菴印可，叹为‘法海透网金鳞’。后结草庵于湖州霞雾山天湖岩穴三十余年，所作《山居诗》百八十余首天下风行。晚年应请住持嘉禾福源禅寺七载，元廷赐金襴衣，淡然处之。高丽僧太古普愚渡海求法，亲获印记付衣。至正十二年书‘光前绝后一堆柴’辞世，寿八十一。",
    "teachings": "提倡‘破死句而契活句’，直断文字意解之知见缠缚；极力阐扬山林隐修与市井住持动静一如，标树‘无山不带云，有水皆含月’之圆融宗风。其《山居诗》全自真如性海中脱颖而出，以极致淡泊平淡之境显发如来无上妙智。",
    "quotes": [
      "无山不带云，有水皆含月。",
      "清明时节雨初晴，黄莺枝上分明语。",
      "玉堂银烛笙歌夜，金谷罗帏富贵家。争似道人茅屋下，一天晴月晒梅花。",
      "青山不着臭尸骸，死了何须掘土埋。顾我也无三昧火，光前绝后一堆柴。"
    ],
