    "id": "weimian",
    "name": "惟勉",
    "title": "后湖比丘 · 丛林清规总要编订者",
    "era": "南宋 (活跃于 1274)",
    "lifeStory": "惟勉法师，南宋末期著名律学与清规律匠，浙江金华后湖比丘，居寄玩轩。法师深究百丈宗门规绳与崇宁清规之流变，因见宋末诸方丛林日用科仪各执己见、抄本多有亏缺，遂发愿博采江南诸大刹藏本，“参其异，存其同，而会焉”，于南宋咸淳十年（1274年）甲戌岁亲手校定撰成《丛林校定清规总要》二卷。书中首创绘制僧堂钵位十六板首图、四节茶汤位次图与尺牍榜式，确立了南宋大丛林两班六头首六知事之完整体制，是元代东村德辉编《禅林备用清规》与朝廷《敕修百丈清规》的直接典范，对东亚禅林制度之传承贡献卓著。",
    "teachings": "主张‘吾氏之有清规，犹儒家之有礼经；礼者从宜，因时损益’。强调戒律为出世根本，清规为丛林安众之纲维；事治则理显，法备则道隆，行住坐卧威仪具备即是真修。",
    "quotes": [
      "吾氏之有清规，犹儒家之有礼经。礼者从宜，因时损益，此书之所以继大智而作也。",
      "戒者止恶防非，规者肃众立范。非规无以集千僧，非戒无以断三毒。",
      "两班共济，如舟之双楫；头首知事，若身之两翼。事治则理显，法备则道隆。",
      "僧堂之内，动静有常。鱼板一响，万籁俱寂。出入无声，视听绝攀。"
    ],
