    "id": "huanxi-weiyi",
    "name": "环溪惟一",
    "title": "太白名山天童景德禅寺住持 · 佛鉴法嗣",
    "era": "宋末元初 (1202–1281)",
    "lifeStory": "环溪惟一禅师（1202—1281），四川资州人，自号环溪，俗姓贾。幼年聪颖，十二岁即对客口诵‘指月知非月’。弱冠祝发，参蜀中土庵圭、讷堂辨诸大老。后东下出峡，造径山参无准师范（佛鉴禅师），契悟玄旨，克承嗣法。宋理宗淳祐六年（1246年）出世住建宁瑞岩，其后历主临江惠力、隆兴宝峰、黄龙崇恩、建昌资圣、黄檗光孝、袁州仰山、福州雪峰，乃至庆元府太白名山天童景德禅寺，凡住持东南名刹九座。禅师宗风峻烈，如迅雷疾风、铁石不移，以‘揽醍醐为毒药’痛剿后学偷心。宋元易代之际，诸方多趋附权门，禅师独抗节不屈，退居白莲峰庵，至元十八年安详示寂，世寿八十，僧腊六十。",
    "teachings": "承继杨岐正宗，主张‘向无窠窟中做成窠窟、活陷平人，今日从头剖析，尽底撤开’；以‘大斧斫了手摩挲’之霹雳手段逼拶学人，令其当下脱落情解，直见父母未生前本来面目。",
    "quotes": [
      "尽大地是门，横开竖辟。通霄有活路，七穴八穿。入门问讳，切忌容易进步。",
      "夜夜明星现，有眼谁不见？此夜老瞿昙，却被明星转。直至而今双眼花，无瑕白玉自生瑕。",
      "见月休观指，犹有月在；归家罢问程，犹有家在。通身是火通身水，烈焰堆中鼓怒涛！",
      "只这便是不思善、不思恶，父母未生已前本来面目。如睡梦觉，如病得汗，一得永得，更无退转。"
    ],
