    "id": "shitian-faxun",
    "name": "石田法薰",
    "title": "灵隐大宗师 / 石田和尚",
    "era": "南宋",
    "lifeStory": "石田法薰禅师（1171—1245），四川眉州彭山赵氏子。早年出蜀遍历荆楚淮浙，登中峰参松源崇岳禅师（密庵咸杰法嗣），得大彻心印，承嗣其法。历主平江高峰、苏州枫桥普明、建康蒋山太平兴国、杭州净慈报恩光孝，晚年住持临安灵隐景德禅寺。早年住平江高峰寺时极端清苦，单丁行乞度日，开炉日视学者曰“些子死柴头上火，大家着力试吹看！”后住枫桥入圆悟关云“虽是旧时车子，山僧也要横推！”显现临济儿孙杀活大机，痴绝道冲、浙翁如琰皆推许避席。淳祐四年退居东堂，示寂前留最后垂诲：“但得本，莫愁末。末后一句子，平地起风波。咄！”趺坐而化，世称石田和尚。",
    "teachings": "认取祖翁荒田，随水牯牛牵犁拽杷；死柴头上火，大家试吹看；虽是旧车，横推过关；但得其本，莫愁其末。 其教法峻洁直截，力矫两宋口头文字禅之流弊，直透本来面目。",
