    "id": "zeshan-yixian",
    "name": "泽山一咸",
    "title": "东林一咸 / 备用清规编纂宗师",
    "era": "元代",
    "lifeStory": "泽山一咸禅师（1254—1328），四明慈溪周氏子。早年依南屏石林和尚，见大川、笑翁二祖遗风；后依承天觉庵禅师，扣问向上心宗大义。历住永嘉天宁、番易永福，大德末年迁住庐山东林太平兴龙禅寺。师见百丈清规年深日久诸方多有传讹，乃博访两浙江淮耆宿，历三十载遍考丛林制度沿革，以《千字文》编次门目，于至大四年（1311）撰成《禅林备用清规》十卷。元大儒袁桷序其书称赞‘清严峻整，讲道不辍，作备用十卷以拯其极坏’；天童云岫赞其‘威仪细行，详释尽美’。此书成为元顺帝颁行《敕修百丈清规》最主要的参考蓝本，对后世东亚禅宗丛林规制产生了极为深远的影响。",
    "teachings": "清规因时损益、备而不用；外严威仪细行以治身心，内契本来觉性以安僧团。以香烛茶汤为礼、钟鱼鼓板为乐，使千百禅僧和合精进、动静不乱。",
    "quotes": [
      "目曰禅林备用清规，备而不用之谓也。知我罪我，其惟春秋。",
      "礼于世为大经，而人情之节文也。沿革损益以趍时，故古今之人情得；纲常制度以拨道，故天地之大经在。",
      "夫钟鱼鼓板，警众朝昏。不越准绳，千古号令。",
      "晓钟者，破长夜，警睡眠；昏钟者，觉昏衢，苏蒙昧。"
    ],
